INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','present-simple-be','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"present-simple-be","title":"Present simple: be","level":"A1","order":4,"summary":"Match am, is and are to the subject, then build statements, negatives and questions.","learningGoals":["Present forms","Negatives and questions","Contractions"],"guidance":"Read the short rules and examples, then complete a 20-question session. Use feedback to explain each choice. Revisit the skill you missed before trying again.","rules":[{"title":"Present forms","explanation":"Use am with I, is with a singular subject, and are with you or a plural subject. Be describes identity, location or a state.","examples":["I am near the exit.","The keys are on a hook."]},{"title":"Negatives and questions","explanation":"Place not after be. For a standard yes/no question, put be before the subject. Do not add do or does.","examples":["The door is not locked.","Are the seats free?"]},{"title":"Contractions","explanation":"In everyday English, I am becomes I’m and they are becomes they’re. Full forms remain correct. In positive short answers, keep the full verb.","examples":["Yes, we are.","No, it is not."]}],"tips":["Read the full context before choosing.","Check the explanation, including after a correct answer.","A passing practice session is useful feedback, not a language certificate."],"source":"seed","provenance":{"version":"foundations-2026-09-v1","authorship":"Grammacho; generated offline with AI assistance","kind":"original-guidance-aligned","reviewStatus":"automated-checked; educator-review-pending","referenceIds":["bc-be","pcc-esol"],"assessment":"Practice only; levels are approximate teaching labels, not validated CEFR assessment."},"quizItems":[{"id":"c35eff66-ed59-5368-aecb-a254cdcbd00f","topicSlug":"present-simple-be","level":"A1","prompt":"I ____ ready for the music lesson.","choices